write_file: {'content': 'import os
from requests.utils import get_netrc_auth

def test_netrc_variants():
    tests = [
        ("machine example.com login pass", "http://example.com", ("login", "pass"), "Standard entry"),
        ("machine example.com : pass", "http://example.com", ("", "pass"), "Empty login"),
        ("machine example.com login :", "http://example.com", ("login", ""), "Empty password"),
        ("machine example.com", "http://example.com", None, "Empty entry"),
        ("machine other.com login pass", "http://example.com", None, "Wrong host"),
    ]

    for content, url, expected, desc in tests:
        netrc_path = f"/tmp/.netrc_{hash(content)}"
        with open(netrc_path, "w") as f:
            f.write(content + "\n")

        os.environ["NETRC"] = netrc_path
        try:
            auth = get_netrc_auth(url)
            print(f"{desc}: {auth!r} == {expected!r}")
            assert auth == expected, f"{desc} failed: expected {expected!r}, got {auth!r}"
        finally:
            if os.path.exists(netrc_path):
                os.remove(netrc_path)

    if "NETRC" in os.environ:
        del os.environ["NETRC"]

if __name__ == "__main__":
    try:
        test_netrc_variants()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
