from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(name: Optional[str] = Form(None)):
    return {"name": name}

client = TestClient(app)

def test_empty_string_form_value():
    # When name is sent as an empty string, it should be interpreted as None 
    # because the default is None and it's a Form field.
    # According to the issue, currently it might be returning "" which then fails validation
    # if the type was more restrictive, or just incorrectly returning "".
    # Actually, if it's Optional[str] = Form(None), "" should be treated as missing -> None.

    response = client.post("/test", data={"name": ""})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_provided_string_form_value():
    response = client.post("/test", data={"name": "foo"})
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

def test_missing_form_value():
    response = client.post("/test", data={})
    assert response.status_code == 200
    assert response.json() == {"name": None}

if __name__ == "__main__":
    test_empty_string_form_value()
    test_provided_string_form_value()
    test_missing_form_value()
    print("All tests passed!")
